from typing import Any


def _is_numeric_column(fieldnames: list[str], row: dict[str, str], col: str) -> bool:
    """Heuristic: if the value is empty or can't be parsed as float, column may not be numeric."""
    val = row.get(col, "").strip()
    if val == "":
        return False
    try:
        float(val)
        return True
    except ValueError:
        return False


def _detect_numeric_columns(fieldnames: list[str], rows: list[dict[str, str]]) -> set[str]:
    """Detect which columns contain numeric data by scanning all rows."""
    numeric_cols: set[str] = set()
    for col in fieldnames:
        has_numeric = False
        has_non_empty = False
        for row in rows:
            val = row.get(col, "").strip()
            if val == "":
                continue
            has_non_empty = True
            try:
                float(val)
                has_numeric = True
            except ValueError:
                pass
        if has_non_empty and has_numeric:
            numeric_cols.add(col)
    return numeric_cols


def _parse_numeric(val: str | None) -> float | None:
    """Parse a string to float, returning None for empty/invalid values."""
    if val is None:
        return None
    val = val.strip()
    if val == "":
        return None
    try:
        return float(val)
    except ValueError:
        return None


def validate_and_parse(input_path: Path) -> tuple[list[str], list[dict[str, str]], set[str], int, int]:
    """Validate CSV and return parsed data.

    Returns:
        (fieldnames, valid_rows, numeric_columns, total_rows, skipped_rows)
    """
    if not input_path.is_file():
        print(f"Error: input file not found: {input_path}", file=sys.stderr)
        sys.exit(1)

    try:
        with open(input_path, newline="", encoding="utf-8") as f:
            reader = csv.DictReader(f)
            fieldnames = reader.fieldnames
            if not fieldnames:
                print("Error: CSV file has no headers", file=sys.stderr)
                sys.exit(1)
            all_rows = list(reader)
    except csv.Error as e:
        print(f"Error: failed to parse CSV: {e}", file=sys.stderr)
        sys.exit(1)

    total_rows = len(all_rows)

    # Detect which columns are numeric
    numeric_cols = _detect_numeric_columns(fieldnames, all_rows)

    # Validate rows: a row is valid if all its numeric columns have parseable values
    # Rows with missing numeric values are skipped (malformed)
    valid_rows: list[dict[str, str]] = []
    skipped_rows = 0
    for row in all_rows:
        is_valid = True
        for col in numeric_cols:
            val = row.get(col, "").strip()
            if val == "":
                is_valid = False
                break
        if is_valid:
            valid_rows.append(row)
        else:
            skipped_rows += 1

    if skipped_rows > 0:
        print(f"Warning: {skipped_rows} malformed row(s) skipped (missing numeric data)", file=sys.stderr)

    # If ALL rows were skipped, that's still valid (empty result set)
    # but if there are no fieldnames at all, that's an error (already handled above)

    return fieldnames, valid_rows, numeric_cols, total_rows, skipped_rows


