"""robust_report.py — CSV data processing with typed structures,
strict validation, deterministic output, and useful errors."""

from __future__ import annotations

import argparse
import csv
import sys
from dataclasses import dataclass, field
from pathlib import Path
from typing import List, Dict, Any, Optional, Iterator


# ---------------------------------------------------------------------------
# Typed internal structures
# ---------------------------------------------------------------------------

@dataclass(frozen=True)
class ColumnSchema:
    """Declares the expected column names and their types."""
    names: List[str]

    def validate(self, header: List[str], source: str) -> None:
        """Raise ValueError if the file header does not match the schema."""
        if header != self.names:
            raise ValueError(
                f"Schema mismatch in {source!r}: "
                f"expected {self.names}, got {header}"
            )


@dataclass
class NumericField:
    """A column that should contain a finite float value."""
    name: str
    value: Optional[float] = None
    raw: Optional[str] = None

    @property
    def is_valid(self) -> bool:
        return self.value is not None


@dataclass
class Row:
    """One parsed CSV row with strict type checking."""
    index: int
    cells: Dict[str, Any] = field(default_factory=dict)
    errors: List[str] = field(default_factory=list)

    def to_dict(self) -> Dict[str, Any]:
        return dict(self.cells)


@dataclass
class ReportSummary:
    """Deterministic summary computed from a validated dataset."""
    total_rows: int
    valid_rows: int
    malformed_rows: int
    column_names: List[str]
    numeric_columns: List[str]
    numeric_sums: Dict[str, float] = field(default_factory=dict)
    numeric_avgs: Dict[str, float] = field(default_factory=dict)
    numeric_mins: Dict[str, float] = field(default_factory=dict)
    numeric_maxs: Dict[str, float] = field(default_factory=dict)


# ---------------------------------------------------------------------------
# Validation helpers
# ---------------------------------------------------------------------------

@dataclass
class ParseError:
    """Structured error describing a malformed row or file."""
    source: str
    line_no: Optional[int]
    message: str

    def __str__(self) -> str:
        part = f"line {self.line_no}" if self.line_no is not None else "file"
        return f"{self.source}: {part} — {self.message}"


def _try_float(value: str, row_index: int, col_name: str, errors: List[str]) -> Optional[float]:
    """Attempt to parse *value* as float; record error on failure."""
    stripped = value.strip()
    if stripped == "":
        errors.append(f"row {row_index}: empty value for {col_name!r}")
        return None
    try:
        f = float(stripped)
        if f != f:  # NaN check
            errors.append(f"row {row_index}: NaN in {col_name!r}")
            return None
        if f == float('inf') or f == float('-inf'):
            errors.append(f"row {row_index}: infinity in {col_name!r}")
            return None
        return f
    except (ValueError, OverflowError):
        errors.append(f"row {row_index}: cannot parse {stripped!r} as number in {col_name!r}")
        return None


# ---------------------------------------------------------------------------
# Core processing engine
# ---------------------------------------------------------------------------

class DatasetProcessor:
    """Reads, validates, and analyses a CSV dataset."""

    def __init__(self, filepath: str) -> None:
        self._path = Path(filepath)
        self._header: List[str] = []
        self._rows: List[Row] = []
        self._errors: List[ParseError] = []
        self._summary: Optional[ReportSummary] = None

    # -- reading -----------------------------------------------------------

    def _open(self) -> None:
        if not self._path.is_file():
            raise FileNotFoundError(f"Input file not found: {self._path}")
        if self._path.stat().st_size == 0:
            self._errors.append(ParseError(str(self._path), None, "file is empty"))
            return
        with self._path.open(newline='', encoding='utf-8') as fh:
            reader = csv.reader(fh)
            try:
                self._header = next(reader)
            except StopIteration:
                self._errors.append(ParseError(str(self._path), None, "file has no header row"))
                return

    # -- parsing -----------------------------------------------------------

    def _parse_rows(self) -> None:
        if not self._header:
            return
        numeric_cols = self._detect_numeric_columns()
        with self._path.open(newline='', encoding='utf-8') as fh:
            reader = csv.reader(fh)
            next(reader)  # skip header
            for row_idx, raw_row in enumerate(reader, start=1):
                row = Row(index=row_idx)
                # Align cells to header; missing columns → None
                for ci, col in enumerate(self._header):
                    if ci < len(raw_row):
                        val = raw_row[ci]
                    else:
                        val = None
                    if col in numeric_cols:
                        if val is None or val.strip() == "":
                            row.errors.append(f"row {row_idx}: empty value for {col!r}")
                            row.cells[col] = None
                        else:
                            parsed = _try_float(val, row_idx, col, row.errors)
                            row.cells[col] = parsed
                    else:
                        row.cells[col] = val if val is not None else ""
                if row.errors:
                    self._errors.append(ParseError(str(self._path), row_idx, "; ".join(row.errors)))
                self._rows.append(row)

    # -- analysis ----------------------------------------------------------

    def _detect_numeric_columns(self) -> List[str]:
        numeric: List[str] = []
        for col in self._header:
            has_numeric = False
            has_non_numeric = False
            for row in self._rows:
                v = row.cells.get(col)
                if v is None:
                    has_non_numeric = True
                    continue
                if isinstance(v, (int, float)):
                    has_numeric = True
                else:
                    has_non_numeric = True
                if has_numeric and has_non_numeric:
                    break
            if has_numeric and not has_non_numeric:
                numeric.append(col)
        return sorted(numeric)

    def _build_summary(self) -> ReportSummary:
        numeric_cols = self._detect_numeric_columns()
        sums: Dict[str, float] = {c: 0.0 for c in numeric_cols}
        count: Dict[str, int] = {c: 0 for c in numeric_cols}
        mins: Dict[str, float] = {c: float('inf') for c in numeric_cols}
        maxs: Dict[str, float] = {c: float('-inf') for c in numeric_cols}
        valid = 0
        malformed = 0
        for row in self._rows:
            if row.errors:
                malformed += 1
            else:
                valid += 1
            for c in numeric_cols:
                v = row.cells.get(c)
                if isinstance(v, (int, float)):
                    sums[c] += float(v)
                    count[c] += 1
                    if v < mins[c]:
                        mins[c] = v
                    if v > maxs[c]:
                        maxs[c] = v

        avgs: Dict[str, float] = {}
        for c in numeric_cols:
            if count[c] > 0:
                avgs[c] = round(sums[c] / count[c], 10)
                # Round to 2 decimal places for deterministic output
                avgs[c] = round(avgs[c], 2)
            else:
                avgs[c] = 0.0

        # Round sums, mins, maxs to 2 decimals for determinism
        for c in numeric_cols:
            sums[c] = round(sums[c], 2)
            if mins[c] != float('inf'):
                mins[c] = round(mins[c], 2)
            if maxs[c] != float('-inf'):
                max

