/**
 * general_tool.ts — General-purpose automation tool (TypeScript).
 *
 * Reads a CSV file, validates the header and numeric fields,
 * calculates totals, and writes a Markdown summary report.
 * Follows the current procedure from procedures/current.md:
 *   1. Export monthly sales CSV
 *   2. Validate header and numeric fields
 *   3. Calculate total revenue and units
 *   4. Save summary as reports/monthly-sales.md
 *   5. Review result before sharing
 */

interface Row {
  [key: string]: string;
}

interface ColumnMap {
  units?: string;
  revenue?: string;
}

function detectColumns(header: string[]): ColumnMap {
  const lower = header.map((h) => h.toLowerCase().trim());
  const result: ColumnMap = {};

  for (let i = 0; i < lower.length; i++) {
    const col = lower[i];
    // Units
    if (col === 'units' || col === 'qty_sold' || col === 'qty') {
      result.units = header[i];
    }
    // Revenue
    if (
      col === 'revenue' ||
      col === 'gross_usd' ||
      col === 'amount' ||
      col === 'total'
    ) {
      result.revenue = header[i];
    }
  }
  return result;
}

function parseNumber(val: string): number | null {
  if (val === undefined || val === null || val.trim() === '') return null;
  const n = parseFloat(val);
  return isNaN(n) ? null : n;
}

function readCSV(filePath: string): { header: string[]; rows: Row[] } {
  const fs = require('fs');
  if (!fs.existsSync(filePath)) {
    throw new Error(`File not found: ${filePath}`);
  }
  const content = fs.readFileSync(filePath, 'utf-8').trim();
  if (content === '') {
    return { header: [], rows: [] };
  }
  const lines = content.split(/\r?\n/);
  const header = lines[0].split(',').map((h) => h.trim());
  const rows: Row[] = [];
  for (let i = 1; i < lines.length; i++) {
    const vals = lines[i].split(',').map((v) => v.trim());
    if (vals.length === 0 || (vals.length === 1 && vals[0] === '')) continue;
    if (vals[0].startsWith('#')) continue; // skip comments
    const row: Row = {};
    for (let j = 0; j < header.length; j++) {
      row[header[j]] = j < vals.length ? vals[j] : '';
    }
    rows.push(row);
  }
  return { header, rows };
}

function main(): void {
  const args = process.argv.slice(2);
  const flagMap: { [key: string]: string } = {};
  for (let i = 0; i < args.length; i++) {
    if (args[i].startsWith('--')) {
      const key = args[i].slice(2);
      const next = args[i + 1];
      if (next && !next.startsWith('--')) {
        flagMap[key] = next;
        i++;
      } else {
        flagMap[key] = '';
      }
    }
  }

  const inputFile = flagMap['input'];
  const outputFile = flagMap['output'];

  if (!inputFile) {
    console.error('Usage: general_tool.ts --input <file.csv> --output <report.md>');
    process.exit(1);
  }

  try {
    const { header, rows } = readCSV(inputFile);

    if (header.length === 0) {
      const report =
        `# Validation Report\n\n` +
        `**File:** ${inputFile}\n\n` +
        `**Status:** EMPTY — no header or data found.\n`;
      if (outputFile) {
        const fs = require('fs');
        const outDir = outputFile.substring(0, outputFile.lastIndexOf('/'));
        if (outDir) {
          const path = require('path');
          fs.mkdirSync(outDir, { recursive: true });
        }
        fs.writeFileSync(outputFile, report, 'utf-8');
      }
      console.log(report);
      process.exit(0);
    }

    const colMap = detectColumns(header);

    // Validate: we need at least units or revenue column
    if (!colMap.units && !colMap.revenue) {
      console.error(
        `ERROR: Cannot detect units/revenue columns from header: ${header.join(', ')}`
      );
      process.exit(1);
    }

    let totalUnits = 0;
    let totalRevenue = 0;
    let validRows = 0;
    const errors: string[] = [];

    for (let i = 0; i < rows.length; i++) {
      const row = rows[i];
      if (colMap.units) {
        const u = parseNumber(row[colMap.units]);
        if (u === null && row[colMap.units] !== undefined && row[colMap.units] !== '') {
          errors.push(`Row ${i + 2}: non-numeric units value "${row[colMap.units]}"`);
        } else if (u !== null) {
          totalUnits += u;
          validRows++;
        }
      }
      if (colMap.revenue) {
        const r = parseNumber(row[colMap.revenue]);
        if (r === null && row[colMap.revenue] !== undefined && row[colMap.revenue] !== '') {
          errors.push(`Row ${i + 2}: non-numeric revenue value "${row[colMap.revenue]}"`);
        } else if (r !== null) {
          totalRevenue += r;
          validRows++;
        }
      }
    }

    const report =
      `# Monthly Sales Summary\n\n` +
      `**File:** ${inputFile}\n\n` +
      `**Valid rows:** ${validRows}\n` +
      `**Total units:** ${totalUnits}\n` +
      `**Total revenue:** ${totalRevenue.toFixed(2)}\n\n`;

    if (errors.length > 0) {
      report += `## Validation Warnings\n\n`;
      errors.forEach((e) => {
        report += `- ${e}\n`;
      });
    }

    // Save report
    if (outputFile) {
      const fs = require('fs');
      const outDir = outputFile.substring(0, outputFile.lastIndexOf('/'));
      if (outDir) {
        const path = require('path');
        fs.mkdirSync(outDir, { recursive: true });
      }
      fs.writeFileSync(outputFile, report, 'utf-8');
    }

    // Always print to stdout for review
    console.log(report);

    if (errors.length > 0) {
      console.warn(`Completed with ${errors.length} validation warning(s).`);
      process.exit(0); // still succeed, warnings are not fatal
    } else {
      console.log('Report generated successfully.');
    }
  } catch (err: any) {
    console.error(`ERROR: ${err.message}`);
    process.exit(1);
  }
}

main();

